function drawCalendar(){const y=calendarMonth.getFullYear(),m=calendarMonth.getMonth(),first=new Date(y,m,1).getDay(),days=new Date(y,m+1,0).getDate();$('monthLabel').textContent=y+'. '+String(m+1).padStart(2,'0');$('todayLabel').textContent=new Intl.DateTimeFormat('ko-KR',{dateStyle:'medium',timeZone:'Asia/Seoul'}).format(now);$('selectedDateLabel').textContent=displayDate(selectedDate);$('stat-date').textContent=selectedDate===localDate?'오늘':displayDate(selectedDate);const names=['일','월','화','수','목','금','토'];let html=names.map(n=>'<div class="dow">'+n+'</div>').join('');for(let i=0;i<first;i++)html+='<div class="day blank"></div>';for(let d=1;d<=days;d++){const iso=y+'-'+String(m+1).padStart(2,'0')+'-'+String(d).padStart(2,'0');html+='<button type="button" class="day'+(iso===selectedDate?' selected':'')+(iso===localDate?' today':'')+'" data-date="'+iso+'">'+d+'</button>'}$('calgrid').innerHTML=html;$('calgrid').querySelectorAll('[data-date]').forEach(b=>b.addEventListener('click',()=>{selectedDate=b.dataset.date;drawCalendar();load()}))}
