 const estimated=list.filter(g=>g.probabilityIsEstimate),withheld=estimated.filter(g=>['very-low','low'].includes(g.probabilityConfidence));const visibleProb=list.filter(g=>canShowProbability(g));
 const unresolved=list.filter(g=>!g.country||String(g.country.code||'').toUpperCase()==='INT');const backtest=localPredictionBacktest();
 const missingSource=list.filter(g=>!String(g.source||'').trim());
 const missingLeague=list.filter(g=>!String(g.league||'').trim()||/^(대회 정보 없음|경기 일정)$/i.test(String(g.league||'')));
 const missingTime=list.filter(g=>!String(g.time||'').trim()||/^(시간 미정|tbd|unknown)$/i.test(String(g.time||'')));
 const scoreNum=v=>v!==null&&v!==undefined&&String(v).trim()!==''&&String(v).trim()!=='-'&&Number.isFinite(Number(v));
 const missingLiveScore=live.filter(g=>!scoreNum(g.hs??g.homeScore)||!scoreNum(g.as??g.awayScore));
 const suspiciousScheduled=list.filter(g=>!isLiveGame(g)&&!isFinishedGame(g)&&scoreNum(g.hs??g.homeScore)&&scoreNum(g.as??g.awayScore));
 const keyOf=g=>[g.sportCategory||g.sport||'',g.league||'',g.home||'',g.away||'',String(g.time||'').match(/\b\d{1,2}:\d{2}\b/)?.[0]||''].map(v=>String(v).toLocaleLowerCase().replace(/[^\p{L}\p{N}:]/gu,'')).join('|');
 const seen=new Set();let duplicateCount=0;for(const g of list){const k=keyOf(g);if(seen.has(k))duplicateCount++;else seen.add(k)}
 const officialSource=g=>!/(공개.*데이터|SportScore|ESPN|저장|캐시|cache)/i.test(String(g.source||''))&&/공식|KBO|KOVO|WKBL|KBL|KFA|K리그|대한축구협회|대한핸드볼협회/i.test(String(g.source||''));
 const providerSource=g=>/ESPN|SportScore/i.test(String(g.source||''));
 const officialCount=list.filter(officialSource).length,providerCount=list.filter(g=>!officialSource(g)&&providerSource(g)).length,cachedCount=list.filter(g=>/저장|캐시|cache/i.test(String(g.source||''))).length;
 const pct=(n,d)=>d?Math.round(n/d*100):0,sourcePct=pct(withSource.length,total);
 const requiredPresent=g=>Boolean(String(g.home||'').trim()&&String(g.away||'').trim()&&String(g.league||'').trim()&&String(g.status||'').trim()&&String(g.source||'').trim());
 const completeness=pct(list.filter(requiredPresent).length,total);
 const issueCount=missingSource.length+missingLeague.length+missingLiveScore.length+suspiciousScheduled.length+duplicateCount;
 const changes=recentScoreChanges.filter(c=>list.some(g=>String(g.home||'')===c.home&&String(g.away||'')===c.away));
